import pathlib, json
p = pathlib.Path("tests/shell/project_prompt_scenario.inc")
s = p.read_text()
old = """        if (path == "workspace/activePlateId")
            for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
                if (plate.active)
                    return std::to_string(plate.id.value());
"""
new = """        if (path == "workspace/activePlateId" || path == "workspace/firstObjectId")
            for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
                if (plate.active && (path == "workspace/activePlateId" || !plate.objects.empty()))
                    return std::to_string(path == "workspace/activePlateId" ? plate.id.value() : plate.objects.front().id.value());
"""
assert old in s; s = s.replace(old, new)
s = s.replace("""    // "{{workspace/sessionId}}", "{{workspace/revision}}" and
    // "{{workspace/activePlateId}}" the project now.""", """    // "{{workspace/sessionId}}", "{{workspace/revision}}",
    // "{{workspace/activePlateId}}" and "{{workspace/firstObjectId}}" (the
    // active plate's first object) the project now.""")
p.write_text(s)

p = pathlib.Path("tests/project_prompt/script.json")
s = p.read_text()
reads = {
 '{"record": "petg-restated"}': ('workspace_inspect', {"sections": ["summary", "objects", "intent", "plan"]}),
 '{"record": "loaded-vs-configured"}': ('printer_list', {}),
 '{"record": "reply-in-german"}': ('workspace_inspect', {"sections": ["summary", "objects", "intent", "plan"]}),
 '{"record": "issue-fix"}': ('settings_get', {"scope": "object", "target": {"objectId": "{{workspace/firstObjectId}}"}, "keys": ["initial_layer_print_height", "layer_height"]}),
 '{"record": "first-person"}': ('settings_get', {"scope": "process", "keys": ["enable_support", "support_type", "support_style"]}),
}
for old, (tool, args) in reads.items():
    assert s.count(old) == 1, old
    name = json.loads(old)["record"]
    s = s.replace(old, json.dumps({"record": name, "call": tool, "arguments": args}) + ", " + json.dumps({"record": name + "-after-read"}))
json.loads(s)
p.write_text(s)
EOF
