import sys, json, re
sys.path.insert(0, "tests/project_prompt"); import run_prompt_tests as t
recorded = {}
for a in t.REQUESTS["advice-infill"]["answers"]:
    if a["tool"] == "settings_get":
        o = json.loads(a["output"])["result"]
        sc = a["arguments"]["scope"]
        recorded.setdefault(sc, set()).update([i["key"] for i in o["items"]] + [u["key"] for u in o.get("unknownKeys", [])])
for line in open("$S/wide-run.out"):
    m = re.match(r"(\S+) run 1/1: unobserved: .*no recorded answer for (settings_get|settings_search) (\{.*\})\s*$", line)
    if m:
        args = json.loads(m.group(3))
        if m.group(2) == "settings_get":
            print(m.group(1), "missing keys:", [k for k in args["keys"] if k not in recorded.get(args["scope"], set())], "scope", args["scope"], "target", args.get("target"))
        else:
            print(m.group(1), "search:", args)
EOF

